using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns information about a topic in a forum supergroup chat or a chat with a bot with topics
    /// </summary>
    public Task<TdLib.TdApi.Objects.ForumTopic> GetForumTopicAsync(long chatId = default, int forumTopicId = default)
    {

           using var activity =  StartCallActivity("GetForumTopicAsync", typeof(GetForumTopic).FullName ?? "GetForumTopicAsync");

           try
           {
             return client.GetForumTopicAsync(chatId, forumTopicId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
